def localize_signals(signals: list[SafetySignal], language: str) -> list[SafetySignal]:
    mapping = SIGNAL_COPY.get(language, {})
    localized = []
    for signal in signals:
        copy = mapping.get(signal.code)
        if copy:
            localized.append(signal.model_copy(update={"title": copy[0], "detail": copy[1]}))
        else:
            localized.append(signal)
    return localized
